def rate_limit(leak_rate, capacity, clock):
    if leak_rate < 0:
        raise ValueError("leak_rate must be non-negative")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")

    def decorator(func):
        water = 0.0
        last_leak = None

        def wrapped(*args, **kwargs):
            nonlocal water, last_leak
            now = clock()
            if last_leak is not None:
                water = max(0.0, water - (now - last_leak) * leak_rate)
            last_leak = now

            if water + 1 <= capacity:
                water += 1.0
                return func(*args, **kwargs)
            return False

        return wrapped

    return decorator

